   270→ * testUlid('TASK', 1) // '01TASK00000001000000000001'
   271→ * testUlid('TRAIT')   // '01TRAJT0000000000000000000' (I replaced with J)
   272→ */
   273→export function testUlid(prefix = '', sequence = 0): string {
   274→  // Replace invalid Crockford chars: I->J, L->K, O->0, U->V
   275→  const safePrefix = prefix.toUpperCase()
   276→    .replace(/I/g, 'J')
   277→    .replace(/L/g, 'K')
   278→    .replace(/O/g, '0')
   279→    .replace(/U/g, 'V');
   280→
   281→  // Start with timestamp-like prefix (01 = valid ULID start)
   282→  const base = '01' + safePrefix;
   283→
   284→  // Pad with zeros, leaving room for sequence and checksum
   285→  const padLength = 24 - base.length; // 26 - 2 for suffix
   286→  const sequenceStr = sequence.toString().padStart(Math.min(padLength, 8), '0');
   287→  const padded = base + sequenceStr.slice(0, padLength);
   288→
   289→  // Fill remaining with zeros and add a final valid char
   290→  const filled = padded.padEnd(25, '0');
   291→
   292→  // Use a deterministic final char based on sequence for uniqueness
   293→  const finalChar = CROCKFORD_BASE32[sequence % 32];
   294→
   295→  return (filled + finalChar).slice(0, 26);
   296→}
   297→
   298→/**
   299→ * Generate multiple unique test ULIDs with the same prefix
   300→ *
   301→ * @param prefix - Prefix for all ULIDs
   302→ * @param count - Number of ULIDs to generate
   303→ * @returns Array of unique valid ULIDs
   304→ *
   305→ * @example
   306→ * const [id1, id2, id3] = testUlids('TASK', 3);
   307→ */
   308→export function testUlids(prefix: string, count: number): string[] {
   309→  return Array.from({ length: count }, (_, i) => testUlid(prefix, i));
   310→}
   311→
```

