if (debug && child.stderr) {
  let stderrData = "";
  child.stderr.on("data", (chunk: Buffer) => { stderrData += chunk.toString(); });
  child.on("close", (code: number | null) => {
    if (code !== 0 && stderrData) {
      console.error(`[DEBUG] Shadow push failed (exit ${code}): ${stderrData.trim()}`);
